struct Item {
    int value;
    int priority;
};

std::vector<Item> items = /* ... */;

// 1. Lambda Comparator: Sort primarily by priority (descending)
std::sort(items.begin(), items.end(),
    [](const Item& a, const Item& b) {
        return a.priority > b.priority;
    }
);

// 2. Functor Comparator: Find the element with the lowest priority
struct PriorityLess {
    bool operator()(const Item& a, const Item& b) const {
        return a.priority < b.priority;
    }
};

auto lowest = std::min_element(items.begin(), items.end(), PriorityLess{});
